// CSD_RATIONALE_BEGIN
// Strategy: hard-masked ConstrainedStep inside spans to eliminate invalid tokens
// (braces, **, LaTeX) inside spans. FIX: hard-masked ConstrainedStep.
//
// New strategy = reference pattern with ConstrainedStep + CloseSpanIfComplete:
//   1. Phase 1: UnconstrainedStep loop; enter constrained mode when
//      RenderedEndsWith(generated, "<<") is detected.
//   2. Phase 2: EACH iteration first calls CloseSpanIfComplete (cost 0 on
//      no-op, cost 1 on close). If not closed, calls hard-masked ConstrainedStep
//      (cost 1). Grammar-invalid tokens are IMPOSSIBLE inside the span.
//      CloseSpanIfComplete fires at the FIRST complete parse -> no loops.
//
// Expected: syntax ~95%+ (hard mask + immediate-close); accuracy maintained/
// improved through stronger guidance reinforcing int() and final-answer placement.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// 1. parser_validity: insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//    Initialization: insideConstrainedOut := insideConstrained,
//    currentConstrainedOut := currentConstrained. Precondition directly gives
//    insideConstrained ==> parser.IsValidPrefix(currentConstrained). ✓
//
//    Free branch (insideConstrainedOut = false):
//      insideConstrainedOut flips to true only when RenderedEndsWith(generated,"<<"),
//      simultaneously setting currentConstrainedOut := []. The method precondition
//      requires parser.IsValidPrefix([]), so the implication holds. ✓
//
//    Constrained close branch (closed = true):
//      CloseSpanIfComplete postcondition guarantees
//      !insideConstrainedOut ==> currentConstrainedOut == [] and
//      insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//      Both cases satisfy the invariant. ✓
//
//    Constrained step branch (closed = false):
//      ConstrainedStep only returns tokens that are parser-valid next tokens at
//      currentConstrainedOut. IsTokenValidNext confirms validity before
//      AppendConstrainedToken, so parser.IsValidPrefix(currentConstrainedOut + [next])
//      holds after append. ✓
//
// 2. progress: |generated| <= |generatedPrefix| + steps
//
//    Per loop iteration, steps increments by exactly 1. Visible generated grows
//    by at most 1 per step:
//    - Free branch: appends at most 1 non-EOS token; steps += 1. ✓
//    - Close branch (closed=true): CloseSpanIfComplete appends ">>" (1 token);
//      steps += 1. CloseSpanIfComplete costs exactly 1 step here. ✓
//    - Close branch (closed=false) + ConstrainedStep: CloseSpanIfComplete costs 0
//      (no step increment), ConstrainedStep costs 1 (steps += 1), and
//      AppendConstrainedToken appends at most 1 visible token. ✓
//    Total: each branch uses exactly 1 token budget, matching the steps increment.
//    cost := steps <= maxSteps at end. Liveness: maxSteps > 0 means first
//    iteration executes, steps >= 1, so cost >= 1 > 0. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

if maxSteps == 0 {
  cost := 0;
} else {
  helpers.AppendTaskGuidance(lm, "Solve step by step using plain text. Write your final answer on the last line as <<int(expr)>> or <<expr>>. Inside << >>: ONLY variable names (no {braces}), integers, +, -, *, /, //, %, (, ), int(). No ** operator, no LaTeX, no spaces inside expression. ALWAYS use int() for integer results. Examples: <<int(n*price+base)>>, <<total-2*n-m>>, <<int((a+b)*c/60)>>. One << >> at the very end only.");

  var steps: nat := 0;

  while steps < maxSteps
    invariant 0 <= steps <= maxSteps
    invariant lm.ValidTokensIdsLogits()
    invariant !insideConstrainedOut ==> currentConstrainedOut == []
    invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
    invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
    invariant |generated| <= |generatedPrefix| + steps
    decreases maxSteps - steps
  {
    if !insideConstrainedOut {
      var next := helpers.UnconstrainedStep(lm, prompt, generated);
      steps := steps + 1;
      if next == eosToken {
        break;
      }
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    } else {
      var cg, ci, cc, closed := helpers.CloseSpanIfComplete(lm, parser, generated, currentConstrainedOut);
      if closed {
        steps := steps + 1;
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
      } else {
        var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
        var next := helpers.ConstrainedStep(lm, parser, constrainedPrompt, currentConstrainedOut, eosToken);
        steps := steps + 1;
        if next == eosToken {
          break;
        }
        var valid := helpers.IsTokenValidNext(parser, currentConstrainedOut, next);
        if valid {
          var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
          generated := ag;
          insideConstrainedOut := ai;
          currentConstrainedOut := ac;
        }
      }
    }
  }

  cost := steps;
}
